import { readFileSync } from "node:fs";
import { join } from "node:path";

// The schema is read out of the GENERATED `@carbon/database` types
// (`packages/database/src/types.ts` `Row:` blocks). That file is regenerated by
// `pnpm run generate:types` after every migration, so it is the freshest
// machine-readable schema in the repo — fresher than
// `packages/jobs/manifests/schema.json`, which only regenerates when the backup
// check runs.

/** Each relation's name and `Row:` block in the generated types, in order. */
function rowBlocks(text: string): [string, string][] {
  return [
    ...text.matchAll(/\n {6}(\w+): \{\n {8}Row: \{\n([\s\S]*?)\n {8}\}\n/g)
  ].flatMap(([, table, block]) => (table && block ? [[table, block]] : []));
}

const readTypes = (root: string) =>
  readFileSync(join(root, "packages/database/src/types.ts"), "utf-8");

/**
 * Column names per table and view. A view is a legitimate read target and
 * never a write one, so including it costs nothing.
 */
export function loadDbTableColumns(root: string): Map<string, Set<string>> {
  const out = new Map<string, Set<string>>();
  for (const [table, block] of rowBlocks(readTypes(root))) {
    const fields = new Set(
      [...block.matchAll(/^ {10}(\w+)\??:/gm)].map((f) => f[1] ?? "")
    );
    if (fields.size > 0 && !out.has(table)) out.set(table, fields);
  }
  return out;
}

/**
 * Each public TABLE's columns with their generated type text (`Row:` blocks
 * between `public.Tables` and `public.Views`), e.g. `closeStatus` →
 * `Database["public"]["Enums"]["periodCloseStatus"]`. Views are left out: the
 * checks that read this judge writes, and a view is never written.
 */
export function loadDbTableColumnTypes(
  root: string
): Map<string, Map<string, string>> {
  const contents = readTypes(root);
  const start = contents.indexOf("\n  public: {\n    Tables: {\n");
  const end = contents.indexOf("\n    Views: {\n", start);
  const tables =
    start === -1 || end === -1 ? "" : contents.slice(start, end + 1);
  const out = new Map<string, Map<string, string>>();
  for (const [table, block] of rowBlocks(tables)) {
    if (out.has(table)) continue;
    const fields = new Map(
      [...block.matchAll(/^ {10}(\w+): (.+)$/gm)].map(
        (f) => [f[1] ?? "", (f[2] ?? "").trim()] as const
      )
    );
    if (fields.size > 0) out.set(table, fields);
  }
  return out;
}
